    if response.status_code == 200:
        return response.json()
    else:
        print(f"Login GET request failed with status code {response.status_code}")
        return None

def do_login_post(url, username, password):
    login_data = {'username': username, 'password': password}
    response = requests.post(url + '/login', json=login_data)
    if response.status_code == 200:
        return response.json()
    else:
        print(f"Login POST request failed with status code {response.status_code}")
