app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/test.db'
db = SQLAlchemy(app)
bcrypt = Bcrypt(app)

users = db.Table('users',
    db.Column('username', db.String(80), primary_key=True),
    db.Column('password', db.String(80))
)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(80))

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        confirm_password = request.form['confirm-password']
        user_exists = User.query.filter_by(username=username).first()
        if user_exists:
            flash('Username already exists!')
            return render_template('register.html')
        elif password != confirm_password:
            flash('Passwords do not match!')
            return render_template('register.html')
        else:
            hashed_password = bcrypt.generate_password_hash(password).decode('utf-8')
            new_user = User(username=username, password=hashed_password)
            db.session.add(new_user)
            db.session.commit()
        return redirect('/login')
    else:
        return render_template('register.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        user = User.query.filter_by(username=username).first()
        if user and bcrypt.check_password_hash(user.password, password):
            return redirect('/change-email')
        else:
            flash('Invalid username or password!')
            return render_template('login.html')
    else:
        return render_template('login.html')

@app.route('/change-email', methods=['GET', 'POST'])
def change_email():
    user = db.session.query(User).filter_by(username=request.cookies.get('user')).first()
    if request.method == 'POST':
        old_email = request.form['old-email']
        new_email = request.form['new-email']
        confirm_password = request.form['confirm-password']
        user_email = User.query.filter_by(username=request.cookies.get('user')).first()
        if old_email != user_email.username or new_email == user_email.username:
            flash('Old email and new email must be different!')
            return render_template('change-email.html')
        if user and bcrypt.check_password_hash(user.password, confirm_password):
            user.username = new_email
            db.session.commit()
            flash('Email changed successfully!')
            return redirect('/login')
        else:
            flash('Invalid password!')
    else:
        return render_template('change-email.html')

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
```

This code includes three routes: `register`, `login`, and `change-email`. The user needs to be registered first, then log in using their credentials before they can change their email. Users are stored in a SQLite database, and passwords are hashed with bcrypt for security purposes.

The HTML templates for each route are not included here but can be created separately using Flask-Bootstrap or another template engine to make the pages look nice. The template names correspond to the route names (e.g., `register.html` for the registration page)."]

