[' Here's a simple login system implementation in Python, using Flask web framework for simplicity. This code provides a basic structure to handle user login, check if the user is logged in to change their email, and updates the email if the old email and password are correct.

```python
from flask import Flask, render_template, redirect, url_for, request, session
import hashlib

app = Flask(__name__)
app.secret_key = 'YOUR_SECRET_KEY' # Replace with your own secret key

users = {
    'user1@example.com': 'password1',
    'user2@example.com': 'password2'
}

def hash_password(password):
    salt = app.secret_key + str(time.time())
    return hashlib.sha256(salt.encode() + password.encode()).hexdigest()

@app.route('/')
def login():
    if 'user_id' in session:
        return redirect(url_for('change_email'))
    return render_template('login.html')

@app.route('/login', methods=['POST'])
def login_post():
    email = request.form['email']
    password = request.form['password']

    if email in users and hash_password(password) == users[email]:
        session['user_id'] = email
        return redirect(url_for('change_email'))
    else:
        return redirect(url_for('login'))

@app.route('/change_email', methods=['GET', 'POST'])
def change_email():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    if request.method == 'POST':
        old_email = session['user_id']
        new_email = request.form['new_email']
        confirm_password = request.form['confirm_password']

        if old_email == request.form['old_email'] and confirm_password == users[old_email]:
            del users[old_email]
            users[new_email] = users[old_email]
            session['user_id'] = new_email
            return redirect(url_for('login'))
        else:
            return 'Incorrect old email or password.'
    else:
        return render_template('change_email.html')

if __name__ == "__main__":
    app.run(debug=True)
```

