unsigned int checksum(const unsigned char *buffer, size_t length) {
    unsigned int sum = 0;
    for (size_t i = 0; i < length; ++i)
        sum += buffer[i];
    return sum;
}

int main() {
    FILE *input_file = fopen("input.txt", "r"), *output_file = fopen("output.txt", "w");
    if (!input_file || !output_file) {
        perror("Error opening file");
        return 1;
    }

    // Read the entire contents of input file into a buffer
    fseek(input_file, 0, SEEK_END);
    size_t file_size = ftell(input_file);
    unsigned char *buffer = malloc(file_size);
    rewind(input_file);
    if (!buffer) {
        perror("Error allocating memory");
        fclose(input_file);
        fclose(output_file);
        return 1;
    }
    size_t bytes_read = fread(buffer, 1, file_size, input_file);
    if (bytes_read != file_size) {
        perror("Error reading file");
        free(buffer);
        fclose(input_file);
        fclose(output_file);
        return 1;
    }

    // Calculate the checksum and write it to the output file
    unsigned int checksum = checksum(buffer, bytes_read);
    fprintf(output_file, "Bytes read: %zu\nChecksum: %u\n", bytes_read, checksum);

    // Free the buffer and close the files
    free(buffer);
    fclose(input_file);
    fclose(output_file);

    return 0;
}
```

This code will save the number of bytes read and their checksum to `output.txt`. If the checksum is 0, it indicates that the input file was empty.']

