unsigned int calculate_checksum(const void *buffer, size_t length) {
    unsigned int checksum = 0;
    const unsigned char *data = buffer;

    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }

    return checksum;
}

int main(void) {
    FILE *input_file, *output_file;
    char *buffer;
    size_t bytes_read = 0;
    unsigned int checksum = 0;

    input_file = fopen("input.txt", "r");
    if (!input_file) {
        perror("Error opening input file");
        return 1;
    }

    output_file = fopen("output.txt", "w");
    if (!output_file) {
        perror("Error opening output file");
        fclose(input_file);
        return 1;
    }

    buffer = malloc(1024 * sizeof(char)); // Allocate a buffer of 1KB
    while ((bytes_read = getline(&buffer, &maxlen, input_file)) != EOF) {
        checksum = calculate_checksum(buffer, bytes_read);
        fprintf(output_file, "Bytes read: %lu\nChecksum: %u\n", bytes_read, checksum);
    }

    free(buffer);
    fclose(input_file);
    fclose(output_file);

    return 0;
}
