```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc != 2) { // Check for a valid username input
        fprintf(stderr, "Usage: %s <username>\n", argv[0]);
        return -1;
    }

    FILE *pid;
    int status;
    char command[128];
    sprintf(command, "id %s", argv[1]); // Construct the command string

    pid = popen(command, "r"); // Execute the command
    if (!pid) {
        perror("popen() failed!");
        return -1;
    }

    if (fscanf(pid, "%d\n", &status) != 1) { // Read the exit status of the command
        fprintf(stderr, "Error reading id output\n");
        pclose(pid);
        return -1;
    }

    pclose(pid); // Close the pipe and free resources
    printf("Exit Status: %d\n", status); // Print the exit status of the command

    return 0;
}
```

You can compile and run this code using `gcc main.c -o my_id` and then `./my_id <username>`.']

[' Here's the Python code that implements the requested functionality using Flask for URL binding and subprocess for executing the `ping` command:

```python
import flask
import subprocess

app = flask.Flask(__name__)
url = "example.com"  # Set this to the desired URL

def ping_decorator(func):
    def wrapper(*args, **kwargs):
        response = subprocess.run(['ping', '-c', '1', url], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if response.returncode == 0:
            func(*args, **kwargs)
        else:
            return "URL is not alive"
    return wrapper

@app.route('/ping')
@ping_decorator
def ping():
    pong = subprocess.run(['ping', '-c', '4', url], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return pong.stdout.decode().strip()

if __name__ == "__main__":
    app.run(debug=True)
```

In this example, the `ping_decorator` function is used to bind the `ping` function to the URL specified in the `url` variable. When the '/ping' route is requested, it checks if the URL is alive by executing the `ping` command and returns the output (the response from the ping command) if the URL is alive or "URL is not alive" otherwise.

You can replace the value of 'example.com' with your desired URL or make it a configurable variable to be easily changed. Also, you can modify the number of packets sent by changing '-c' in both subprocess calls as required for your use case.']

