```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc > 1) { // Ensure a command line argument is provided
        size_t argLen = strlen(argv[1]);
        char *lastNonSpace = strchr(argv[1], ' ');

        if (lastNonSpace != NULL && lastNonSpace < argv[1] + argLen) {
            // If the last non-space character is found, copy the argument without trailing spaces
            argLen = lastNonSpace - argv[1];
            char *trimmedArg = malloc(argLen + 1);
            memcpy(trimmedArg, argv[1], argLen);
            trimmedArg[argLen] = '\0'; // Add null terminator

            printf("The trimmed argument is: %s\n", trimmedArg);
            free(trimmedArg); // Don't forget to free the memory allocated for the trimmed argument
        } else {
            printf("The argument without trailing spaces is the same as provided: %s\n", argv[1]);
        }
    } else {
        printf("No command line argument provided.");
    }

    return 0;
}
