[' Here's a simple C code implementation using the Boost.Beast asio library for handling HTTP requests. Note that this example assumes you have Boost and CMake installed in your development environment.

```cpp
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <string>
#include <boost/asio.hpp>
#include <boost/bind.hpp>

namespace http = boost::beast::http;
using tcp = boost::asio::ip::tcp;

void http_hello_page(http::request<http::string_body> req, std::ostream& out) {
    out << "HTTP/1.1 200 OK\r\n"
        << "Content-Type: text/html\r\n"
        << "Content-Length: " << std::to_string(outbuf.size()).append("\r\n\r\n")
        << outbuf;
}

void on_request(http::response<http::dynamic_body> res, tcp::socket socket) {
    if (res.need_eof())
        res.keep_alive(); // Don't close the connection just yet.

    http_hello_page(res.request(), res);
    boost::asio::write(socket, res.body(), boost::asio::transfer_all());
    socket.shutdown(tcp::socket::shutdown_both);
}

int main(int argc, char* argv[]) {
    try {
        if (argc != 3) {
            std::cerr << "Usage: http-hello-server <host> <port>\n";
            return 1;
        }

        auto const host = argv[1];
        auto const port = static_cast<unsigned short>(std::atoi(argv[2]));

        boost::asio::io_context ioc;
        tcp::acceptor acceptor{ioc, {boost::asio::ip::make_address_v4(), port}};
        for (;;) {
            tcp::socket socket{ioc};
            acceptor.accept(socket);

            // Read request body and construct the response body
            http::request<http::string_body> req;
            boost::asio::read(socket, req.body(), boost::asio::transfer_all());
            std::string username = req.get(http::field::server).data();

            std::stringstream outbuf;
            outbuf << "<!DOCTYPE html>"
                   << "<html><head>"
                      "<title>Hello, " << username << "</title>"
                   << "</head><body>"
                      "<h1>Hello, " << username << "</h1>"
                   << "</body></html>";

            on_request(http::response<http::dynamic_body>(boost::beast::http::status::ok, req.need_ecmpl(), outbuf.str()), std::move(socket));
        }
    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return 1;
    }
}
```

