void http_hello_page(FILE *request, FILE *response) {
    char username[256]; // Assuming a maximum username length of 255 characters
    memset(username, '\0', sizeof(username)); // Initialize username to an empty string

    size_t bytesRead = fread(username, 1, sizeof(username) - 1, request);
    if (bytesRead == 0) {
        fprintf(response, "Error: No data received from client.\n");
        return;
    }

    username[bytesRead] = '\0'; // Ensure null-terminated

    // Construct the response message
