[' Here is the Python code that implements your requirements:

```python
import functools
import re
from urllib.parse import urlparse, parse_qs, urlencode

def html_escape(text):
    """Function to convert special characters to HTML-safe sequences."""
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

def escape_uri_path(path):
    """Function to escape path for use in URI."""
    reserved = {'/': '%2F', '?': '%3F', '#': '%23'}
    return re.sub('[' + ''.join(reserved.keys()) + ']', functools.partial(reserved.get, ), path)

def url_mapping(url):
    """Decorator creating a mapping between URL and function."""
    def decorate(func):
        def wrapper(*args, **kwargs):
            parsed = urlparse(url)
            query = parse_qs(parsed.query)
            username = query.get('username', ['username'])[0] if 'username' in query else ''
            escaped_path = escape_uri_path(parsed.path)
            if escaped_path == url:
                result = func(*args, username=username)
                return result
            raise ValueError("Invalid URL")
        return wrapper
    return decorate

@url_mapping('/hello/<username>')
def hello(username):
    """Function that returns Hello followed by the value of the variable username."""
    return "Hello " + html_escape(username)

if __name__ == "__main__":
    print(hello("World"))  # Test the function
```

In this code, we have a decorator named `url_mapping` that takes a URL as an argument and creates a mapping between the URL and the function that follows it. The `hello()` function is decorated with the `url_mapping('/hello/<username>')` decorator, which means that when a user navigates to the URL /hello/username, the `hello(username)` function will be called with the value of username set accordingly.

To test the code, you can run it directly:

```bash
python your_file_name.py
```

This should print "Hello World" if you call the script as follows:

